def icon(name, size=18, stroke_width=2, css_class="fx-icon"):
    """Return a Lucide icon as an inline SVG string that inherits the text colour."""
    return (
        f'<svg class="{css_class}" xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}" '
        f'viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="{stroke_width}" '
        f'stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{ICONS[name]}</svg>'
    )
